def broadcast_shapes(s1: tuple[int, ...], s2: tuple[int, ...]) -> tuple[int, ...]:
    n1, n2 = len(s1), len(s2)
    max_len = max(n1, n2)
    p1 = (1,) * (max_len - n1) + s1
    p2 = (1,) * (max_len - n2) + s2
    res = []
    for d1, d2 in zip(p1, p2):
        if d1 == d2:
            res.append(d1)
        elif d1 == 1:
            res.append(d2)
        else:
            raise ValueError(f"Cannot broadcast shapes {s1} and {s2}")
    return tuple(res)
